SELECT wss.*, u.nickname AS student_name, ws.job_name AS job_name FROM t_work_study_student wss LEFT JOIN t_user u ON wss.student_id = u.id LEFT JOIN t_work_study ws ON wss.work_study_id = ws.id
AND wss.work_study_id = #{workStudyId}
AND wss.student_id = #{studentId}
AND wss.work_month = #{workMonth}
AND wss.audit_status = #{auditStatus}
AND ( CAST(wss.student_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR ws.job_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY wss.create_time DESC

